cat > /tmp/probe/fcgi_dump.py <<'EOF'
import socket, struct, os, sys
path = sys.argv[1]
if os.path.exists(path): os.unlink(path)
s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
s.bind(path); os.chmod(path, 0o666); s.listen(5)
def read_exact(c, n):
    b = b''
    while len(b) < n:
        d = c.recv(n - len(b))
        if not d: raise EOFError
        b += d
    return b
def read_record(c):
    h = read_exact(c, 8)
    ver, typ, rid, clen, plen, _ = struct.unpack('>BBHHBB', h)
    body = read_exact(c, clen)
    if plen: read_exact(c, plen)
    return typ, rid, body
def parse_params(b):
    out = {}; i = 0
    while i < len(b):
        def ln():
            nonlocal i
            if b[i] & 0x80:
                v = struct.unpack('>I', b[i:i+4])[0] & 0x7fffffff; i += 4
            else:
                v = b[i]; i += 1
            return v
        kl = ln(); vl = ln()
        out[b[i:i+kl].decode(errors='replace')] = b[i+kl:i+kl+vl].decode(errors='replace'); i += kl + vl
    return out
def send(c, typ, rid, body):
    c.sendall(struct.pack('>BBHHBB', 1, typ, rid, len(body), 0, 0) + body)
log = open('/tmp/probe/fcgi_params.log', 'a')
while True:
    c, _ = s.accept()
    params = b''; rid = 1
    while True:
        try:
            typ, rid, body = read_record(c)
        except EOFError:
            break
        if typ == 4:
            if body == b'':
                break
            params += body
        elif typ == 5 and body == b'':
            break
    p = parse_params(params)
    log.write(repr(p) + "\n"); log.flush()
    out = b"Content-Type: text/plain\r\n\r\nhello dump\n"
    send(c, 6, rid, out); send(c, 6, rid, b''); send(c, 3, rid, struct.pack('>IBBBB', 0, 0, 0, 0, 0))
    c.close()
EOF
