520	  # Apache. Starts as root; workers run as www-data; mod_wsgi daemons and
   521	  # CGI executors run as the tenant.
   522	  services.httpd = {
   523	    enable = true;
   524	    package = apache;
   525	    user = "www-data";
   526	    group = "www-data";
   527	    configFile = httpdConf;
   528	    logFormat = "none";
   529	  };
   530	  systemd.services.httpd = {
   531	    aliases = [ "apache2.service" ];
   532	    serviceConfig = {
   533	      User = lib.mkForce "root";
   534	      Group = lib.mkForce "root";
   535	      RuntimeDirectoryMode = lib.mkForce "0755";
   536	      AmbientCapabilities = lib.mkForce [ ];
   537	    };
   538	  };
   539	
   540	  services.fcgiwrap.instances = lib.mapAttrs (name: _: mkTenantCgi name) tenants;
   541	
   542	  services.phpfpm.pools = lib.mapAttrs (name: _: mkTenantFpm name) tenants;
   543	  # Pools run unsandboxed like the reference (tenant homes and /tmp stay visible).
   544	  systemd.services."phpfpm-amber".serviceConfig = fpmUnsandboxed;
   545	  systemd.services."phpfpm-cobalt".serviceConfig = fpmUnsandboxed;
   546	  # One operator-facing unit for both tenant FPM pools, as on the reference.
   547	  systemd.services."phpfpm-amber".partOf = [ "php8.1-fpm.service" ];
   548	  systemd.services."phpfpm-cobalt".partOf = [ "php8.1-fpm.service" ];
   549	  systemd.services."php8.1-fpm" = {
   550	    description = "PHP FastCGI Process Manager (tenant pools)";
   551	    wantedBy = [ "multi-user.target" ];
   552	    requires = [ "phpfpm-amber.service" "phpfpm-cobalt.service" ];
   553	    after = [ "phpfpm-amber.service" "phpfpm-cobalt.service" ];
   554	    serviceConfig = {
   555	      Type = "oneshot";
   556	      RemainAfterExit = true;
   557	      ExecStart = "${pkgs.coreutils}/bin/true";
   558	    };
   559	  };
   560	  systemd.services.sshd.aliases = [ "ssh.service" ];
   561	  systemd.services.syslog.aliases = [ "rsyslog.service" ];
   562	
   563	  services.rsyslogd = {
   564	    enable = true;
   565	    defaultConfig = "";
   566	    extraConfig = ''
   567	      $ActionFileDefaultTemplate RSYSLOG_TraditionalFileFormat
   568	      $FileOwner syslog
   569	      $FileGroup adm
   570	      $FileCreateMode 0640
   571	      auth,authpriv.*                 /var/log/auth.log
   572	      *.*;auth,authpriv.none          -/var/log/syslog
   573	      kern.*                          -/var/log/kern.log
   574	      cron.*                          /var/log/cron.log
   575	    '';
   576	  };
   577	  # suexec-style clean environment for tenant CGI.
   578	  systemd.services."fcgiwrap-amber".serviceConfig.UnsetEnvironment = cgiCleanEnv;
   579	  systemd.services."fcgiwrap-cobalt".serviceConfig.UnsetEnvironment = cgiCleanEnv;
   580	
   581	  services.memcached = {
   582	    enable = true;
   583	    user = "memcache";
   584	    listen = "127.0.0.1";
   585	    port = 11211;
   586	    maxMemory = 32;
   587	    extraOptions = [ "-U" "0" ];
   588	  };
   589	
   590	  services.mysql = {
   591	    enable = true;
   592	    package = pkgs.mariadb;
   593	    settings.mysqld = {
   594	      bind-address = "127.0.0.1";
   595	      port = 3306;
   596	      character-set-server = "utf8mb4";
   597	      collation-server = "utf8mb4_general_ci";
   598	    };
   599	    initialDatabases = [
   600	      { name = "amber"; }
   601	      { name = "cobalt"; }
   602	    ];
   603	    initialScript = mariadbInit;
   604	  };
   605	  systemd.services.mysql.aliases = [ "mariadb.service" ];
